for r in range(4):
    for c in range(4, 7):
        val = original[r][c]
        if val != 6:
            output4[r][6-c] = val

for r in range(5, 9):
    top_row = 8 - r
    for c in range(4, 7):
        val = original[top_row][c]
        if val != 6:
            output4[r][6-c] = val

for row in output4:
    print(" ".join(str(x) for x in row))

print("\nSubmitting left mirror only, no right, no bottom:")
print(json.dumps({"action": "submit", "grid": output4}))

